use self::charset::switch_default_collation;

/// `newCollatorMap` (by name) and `newCollatorIDMap` (by ID).
type CollatorMaps = (
    HashMap<&'static str, Box<dyn Collator>>,
    HashMap<isize, Box<dyn Collator>>,
);

// newCollatorMap, newCollatorIDMap: filled by `init`.
static newCollators: LazyLock<CollatorMaps> = LazyLock::new(init);

static newCollationEnabled: AtomicI32 = AtomicI32::new(1);

// binCollatorInstance is a singleton used for all collations when newCollationEnabled is false.
static binCollatorInstance: DerivedBinCollator = DerivedBinCollator::new();

/// ErrUnsupportedCollation is returned when an unsupported collation is specified.
pub static ErrUnsupportedCollation: LazyLock<Error> = LazyLock::new(|| {
    dbterror::ClassDDL.new_std_err(
        mysql::ErrUnknownCollation,
        &ErrMessage::new(
            "Unsupported collation when new collation is enabled: '%-.64s'",
            &[],
        ),
    )
});
/// ErrIllegalMixCollation is returned when illegal mix of collations.
pub static ErrIllegalMixCollation: LazyLock<Error> =
    LazyLock::new(|| dbterror::ClassExpression.new_std(mysql::ErrCantAggregateNcollations));
/// ErrIllegalMix2Collation is returned when illegal mix of 2 collations.
pub static ErrIllegalMix2Collation: LazyLock<Error> =
    LazyLock::new(|| dbterror::ClassExpression.new_std(mysql::ErrCantAggregate2collations));
/// ErrIllegalMix3Collation is returned when illegal mix of 3 collations.
pub static ErrIllegalMix3Collation: LazyLock<Error> =
    LazyLock::new(|| dbterror::ClassExpression.new_std(mysql::ErrCantAggregate3collations));

/// DefaultLen is set for datum if the string datum don't know its length.
pub const DefaultLen: isize = 0;

/// Collator provides functionality for comparing strings for a given
/// collation order.
pub trait Collator: Send + Sync + Any {
    /// Compare returns an integer comparing the two strings. The result will be 0 if a == b, -1 if a < b, and +1 if a > b.
    // glue: interface method of collate.Collator
    fn compare(&self, a: &[u8], b: &[u8]) -> isize;
    /// Key returns the collate key for str. If the collation is padding, make sure the PadLen >= len(rune[]str) in opt.
    // glue: interface method of collate.Collator
    fn key(&self, str: &[u8]) -> Vec<u8>;
    /// KeyWithoutTrimRightSpace returns the collate key for str. The difference with Key is str will not be trimed.
    // glue: interface method of collate.Collator
    fn key_without_trim_right_space(&self, str: &[u8]) -> Vec<u8>;
    /// Pattern get a collation-aware WildcardPattern.
    // glue: interface method of collate.Collator
    fn pattern(&self) -> Box<dyn WildcardPattern>;
    /// Clone returns a copy of the collator.
    // glue: interface method of collate.Collator
    fn clone_collator(&self) -> Box<dyn Collator>;
    /// The collator as `Any`, for Go's type assertions on the interface (`CanUseRawMemAsKey`).
    // glue: interface method of collate.Collator
    fn as_any(&self) -> &dyn Any;
}

/// WildcardPattern is the interface used for wildcard pattern match.
pub trait WildcardPattern: Send + Sync {
    /// Compile compiles the patternStr with specified escape character.
    // glue: interface method of collate.WildcardPattern
    fn compile(&mut self, pattern_str: &[u8], escape: u8);
    /// DoMatch tries to match the str with compiled pattern, `Compile()` must be called before calling it.
    // glue: interface method of collate.WildcardPattern
    fn do_match(&self, str: &[u8]) -> bool;
}

/// SetNewCollationEnabledForTest sets if the new collation are enabled in test.
/// Note: Be careful to use this function, if this functions is used in tests, make sure the tests are serial.
// go: SetNewCollationEnabledForTest L1
pub fn set_new_collation_enabled_for_test(flag: bool) {
    switch_default_collation(flag);
    if flag {
        newCollationEnabled.store(1, AtomicOrdering::SeqCst);
        return;
    }
    newCollationEnabled.store(0, AtomicOrdering::SeqCst);
}

/// NewCollationEnabled returns if the new collations are enabled.
// go: NewCollationEnabled L1
pub fn new_collation_enabled() -> bool {
    newCollationEnabled.load(AtomicOrdering::SeqCst) == 1
}

/// CompatibleCollate checks whether the two collate are the same.
// go: CompatibleCollate L1
#[allow(clippy::if_same_then_else)] // Go's three branches, kept for side-by-side review
pub fn compatible_collate(collate1: &str, collate2: &str) -> bool {
    if (collate1 == "utf8mb4_general_ci" || collate1 == "utf8_general_ci")
        && (collate2 == "utf8mb4_general_ci" || collate2 == "utf8_general_ci")
    {
        return true;
    } else if (collate1 == "utf8mb4_bin" || collate1 == "utf8_bin" || collate1 == "latin1_bin")
        && (collate2 == "utf8mb4_bin" || collate2 == "utf8_bin" || collate2 == "latin1_bin")
    {
        return true;
    } else if (collate1 == "utf8mb4_unicode_ci" || collate1 == "utf8_unicode_ci")
        && (collate2 == "utf8mb4_unicode_ci" || collate2 == "utf8_unicode_ci")
    {
        return true;
    }
    collate1 == collate2
}

/// RewriteNewCollationIDIfNeeded rewrites a collation id if the new collations are enabled.
/// When new collations are enabled, we turn the collation id to negative so that other the
/// components of the cluster(for example, TiKV) is able to aware of it without any change to
/// the protocol definition.
/// When new collations are not enabled, collation id remains the same.
// go: RewriteNewCollationIDIfNeeded L1
pub fn rewrite_new_collation_id_if_needed(id: i32) -> i32 {
    if newCollationEnabled.load(AtomicOrdering::SeqCst) == 1 {
        if id >= 0 {
            return id.wrapping_neg();
        }
        log::warn!("Unexpected negative collation ID for rewrite. ID={id}");
    }
    id
}

/// RestoreCollationIDIfNeeded restores a collation id if the new collations are enabled.
// go: RestoreCollationIDIfNeeded L1
pub fn restore_collation_id_if_needed(id: i32) -> i32 {
    if newCollationEnabled.load(AtomicOrdering::SeqCst) == 1 {
        if id <= 0 {
            return id.wrapping_neg();
        }
        log::warn!("Unexpected positive collation ID for restore. ID={id}");
    }
    id
}

/// GetCollator get the collator according to collate, it will return the binary collator if the corresponding collator doesn't exist.
// go: GetCollator L1
pub fn get_collator(collate: &str) -> &'static dyn Collator {
    if newCollationEnabled.load(AtomicOrdering::SeqCst) == 1 {
        let m = &newCollators.0;
        return match m.get(collate) {
            Some(ctor) => ctor.as_ref(),
            None => {
                if !collate.is_empty() {
                    log::warn!(
                        "Unable to get collator by name, use binCollator instead. name={collate}"
                    );
                }
                m[gocharset::CollationUTF8MB4].as_ref()
            }
        };
    }
    &binCollatorInstance
}

/// GetBinaryCollator gets the binary collator, it is often used when we want to apply binary compare.
// go: GetBinaryCollator L1
pub fn get_binary_collator() -> &'static dyn Collator {
    &binCollatorInstance
}

/// GetBinaryCollatorSlice gets the binary collator slice with len n.
///
/// Go returns one shared slice for `n == 1`; here every call returns a new `Vec`.
// go: GetBinaryCollatorSlice L1
pub fn get_binary_collator_slice(n: usize) -> Vec<&'static dyn Collator> {
    if n == 1 {
        return vec![&binCollatorInstance];
    }
    let mut collators: Vec<&'static dyn Collator> = Vec::with_capacity(n);
    for _ in 0..n {
        collators.push(&binCollatorInstance);
    }
    collators
}

/// GetCollatorByID get the collator according to id, it will return the binary collator if the corresponding collator doesn't exist.
// go: GetCollatorByID L1
pub fn get_collator_by_id(id: isize) -> &'static dyn Collator {
    if newCollationEnabled.load(AtomicOrdering::SeqCst) == 1 {
        return match newCollators.1.get(&id) {
            Some(ctor) => ctor.as_ref(),
            None => {
                log::warn!("Unable to get collator by ID, use binCollator instead. ID={id}");
                newCollators.0["utf8mb4_bin"].as_ref()
            }
        };
    }
    &binCollatorInstance
}

/// CollationID2Name return the collation name by the given id.
/// If the id is not found in the map, the default collation is returned.
// go: CollationID2Name L1
pub fn collation_id2_name(id: i32) -> String {
    match gocharset::get_collation_by_id(id as isize) {
        // TODO(bb7133): fix repeating logs when the following code is uncommented.
        // logutil.BgLogger().Warn(
        // 	"Unable to get collation name from ID, use default collation instead.",
        // 	zap.Int32("ID", id),
        // 	zap.Stack("stack"))
        Err(_) => mysql::DefaultCollationName.to_owned(),
        Ok(collation) => collation.name.clone(),
    }
}

/// CollationName2ID return the collation id by the given name.
/// If the name is not found in the map, the default collation id is returned
// go: CollationName2ID L1
pub fn collation_name2_id(name: &str) -> isize {
    if let Ok(coll) = gocharset::get_collation_by_name(name) {
        return coll.id;
    }
    mysql::DefaultCollationID
}

/// SubstituteMissingCollationToDefault will switch to the default collation if
/// new collations are enabled and the specified collation is not supported.
// go: SubstituteMissingCollationToDefault L1
pub fn substitute_missing_collation_to_default(co: &str) -> String {
    if get_collation_by_name(co).is_ok() {
        return co.to_owned();
    }
    log::warn!(
        "The collation {co} specified on connection is not supported when new collation is enabled, switch to the default collation: {}",
        mysql::DefaultCollationName
    );
    match get_collation_by_name(gocharset::CollationUTF8MB4) {
        Ok(coll) => coll.name.clone(),
        Err(err) => {
            log::warn!("{err}");
            // Go dereferences the nil *Collation.
            panic!("runtime error: invalid memory address or nil pointer dereference")
        }
    }
}

/// GetCollationByName wraps charset.GetCollationByName, it checks the collation.
// go: GetCollationByName L1 [M-ERR]
pub fn get_collation_by_name(name: &str) -> Result<std::sync::Arc<Collation>, Error> {
    let coll = gocharset::get_collation_by_name(name)?;
    if newCollationEnabled.load(AtomicOrdering::SeqCst) == 1
        && !newCollators.1.contains_key(&coll.id)
    {
        return Err(
            ErrUnsupportedCollation.gen_with_stack_by_args(vec![Arg::from(name.to_owned())])
        );
    }
    Ok(coll)
}

/// GetSupportedCollations gets information for all collations supported so far.
// go: GetSupportedCollations L1
pub fn get_supported_collations() -> Vec<std::sync::Arc<Collation>> {
    if newCollationEnabled.load(AtomicOrdering::SeqCst) == 1 {
        let mut new_supported_collations = Vec::with_capacity(newCollators.0.len());
        for name in newCollators.0.keys() {
            // utf8mb4_zh_pinyin_tidb_as_cs is under developing, should not be shown to user.
            if *name == "utf8mb4_zh_pinyin_tidb_as_cs" {
                continue;
            }
            match gocharset::get_collation_by_name(name) {
                // Should never happens.
                Err(err) => tidb_base::terror::log(Some(&err)),
                Ok(coll) => new_supported_collations.push(coll),
            }
        }
        new_supported_collations.sort_by(|i, j| i.name.cmp(&j.name));
        return new_supported_collations;
    }
    gocharset::get_supported_collations()
}

// go: truncateTailingSpace L1
fn truncate_tailing_space(str: &[u8]) -> &[u8] {
    let mut i = str.len();
    while i > 0 && str[i - 1] == b' ' {
        i -= 1;
    }
    &str[..i]
}

// go: sign L1
fn sign(i: isize) -> isize {
    if i < 0 {
        return -1;
    } else if i > 0 {
        return 1;
    }
    0
}

// go: runeLen L1
fn rune_len(b: u8) -> usize {
    if b < 0x80 {
        return 1;
    } else if b < 0xE0 {
        return 2;
    } else if b < 0xF0 {
        return 3;
    }
    4
}

/// IsDefaultCollationForUTF8MB4 returns if the collation is DefaultCollationForUTF8MB4.
// go: IsDefaultCollationForUTF8MB4 L1
pub fn is_default_collation_for_utf8mb4(collate: &str) -> bool {
    // utf8mb4_bin is used for the migrations/replication from TiDB with version prior to v7.4.0.
    collate == "utf8mb4_bin" || collate == "utf8mb4_general_ci" || collate == "utf8mb4_0900_ai_ci"
}

/// IsCICollation returns if the collation is case-insensitive
// go: IsCICollation L1
pub fn is_ci_collation(collate: &str) -> bool {
    collate == "utf8_general_ci"
        || collate == "utf8mb4_general_ci"
        || collate == "utf8_unicode_ci"
        || collate == "utf8mb4_unicode_ci"
        || collate == "gbk_chinese_ci"
        || collate == "utf8mb4_0900_ai_ci"
}

/// ConvertAndGetBinCollation converts collation to binary collation
// go: ConvertAndGetBinCollation L1
pub fn convert_and_get_bin_collation(collate: &str) -> &str {
    match collate {
        "utf8_general_ci" => "utf8_bin",
        "utf8_unicode_ci" => "utf8_bin",
        "utf8mb4_general_ci" => "utf8mb4_bin",
        "utf8mb4_unicode_ci" => "utf8mb4_bin",
        "utf8mb4_0900_ai_ci" => "utf8mb4_bin",
        "gbk_chinese_ci" => "gbk_bin",
        _ => collate,
    }
}

/// ConvertAndGetBinCollator converts collation to binary collator
// go: ConvertAndGetBinCollator L1
pub fn convert_and_get_bin_collator(collate: &str) -> &'static dyn Collator {
    get_collator(convert_and_get_bin_collation(collate))
}

/// IsBinCollation returns whether the sortkey of a char/varchar under this collation
/// equals the raw data itself. This is a STORAGE-LEVEL property used by:
///   - tablecodec: deciding whether restore-data is needed
///   - NeedRestoredData: padding optimization
///   - ranger/selectivity: assuming sortkey == data for fast paths
///
/// DO NOT use this for coercibility derivation (use expression.isBinCollation instead).
/// The two concepts diverge on GBK: gbk_bin's Key() does UTF-8→GBK encoding conversion
/// (sortkey ≠ data), but it IS still a _bin collation for coercibility purposes.
///
/// Included: ascii_bin, latin1_bin, utf8_bin, utf8mb4_bin, binary, utf8mb4_0900_bin
/// NOT included: gbk_bin (its Key() transforms data via encoding)
// go: IsBinCollation L1
pub fn is_bin_collation(collate: &str) -> bool {
    collate == gocharset::CollationASCII
        || collate == gocharset::CollationLatin1
        || collate == gocharset::CollationUTF8
        || collate == gocharset::CollationUTF8MB4
        || collate == gocharset::CollationBin
        || collate == gocharset::CollationUTF8MB40900Bin
}

/// IsPadSpaceCollation returns whether the collation is a PAD SPACE collation.
// go: IsPadSpaceCollation L1
pub fn is_pad_space_collation(collation: &str) -> bool {
    collation != gocharset::CollationBin
        && collation != "utf8mb4_0900_ai_ci"
        && collation != "utf8mb4_0900_bin"
}

/// CollationToProto converts collation from string to int32(used by protocol).
// go: CollationToProto L1 [M-INT]
pub fn collation_to_proto(c: &str) -> i32 {
    if let Ok(coll) = gocharset::get_collation_by_name(c) {
        return rewrite_new_collation_id_if_needed(coll.id as i32);
    }
    let v = rewrite_new_collation_id_if_needed(mysql::DefaultCollationID as i32);
    log::warn!(
        "Unable to get collation ID by name, use ID of the default collation instead name={c} default collation ID={v} default collation={}",
        mysql::DefaultCollationName
    );
    v
}

/// Go's `compareCommon`: per rune, by a weight function; trailing spaces are not
/// significant; any invalid byte makes the strings equal.
// go: compareCommon L1
fn compare_common(a: &[u8], b: &[u8], key_func: impl Fn(char) -> u32) -> isize {
    let a = truncate_tailing_space(a);
    let b = truncate_tailing_space(b);

    let (mut ai, mut bi) = (0, 0);
    while ai < a.len() && bi < b.len() {
        let (r1, r1_len) = decode_rune(&a[ai..]);
        let (r2, r2_len) = decode_rune(&b[bi..]);
        // When the byte sequence is not a valid UTF-8 encoding of a rune, Golang returns RuneError('�') and size 1.
        // See https://pkg.go.dev/unicode/utf8#DecodeRune for more details.
        // Here we check both the size and rune to distinguish between invalid byte sequence and valid '�'.
        let invalid1 = r1 == char::REPLACEMENT_CHARACTER && r1_len == 1;
        let invalid2 = r2 == char::REPLACEMENT_CHARACTER && r2_len == 1;
        if invalid1 || invalid2 {
            return 0;
        }

        ai += r1_len;
        bi += r2_len;

        let cmp = cmp_compare(key_func(r1), key_func(r2));
        if cmp != 0 {
            return cmp;
        }
    }
    cmp_compare(a.len() - ai, b.len() - bi)
}

/// Go `cmp.Compare` for ordered integers.
// go-std: cmp.Compare L1
fn cmp_compare<T: Ord>(x: T, y: T) -> isize {
    match x.cmp(&y) {
        Ordering::Less => -1,
        Ordering::Equal => 0,
        Ordering::Greater => 1,
    }
}

/// CanUseRawMemAsKey returns true if current collator can use the original raw memory as the key
/// only return true for binCollator and derivedBinCollator
// go: CanUseRawMemAsKey L1
pub fn can_use_raw_mem_as_key(c: &dyn Collator) -> bool {
    if c.as_any().is::<BinCollator>() {
        return true;
    }
    if c.as_any().is::<DerivedBinCollator>() {
        return true;
    }
    false
}

/// ProtoToCollation converts collation from int32(used by protocol) to string.
// go: ProtoToCollation L1
pub fn proto_to_collation(c: i32) -> String {
    if let Ok(coll) = gocharset::get_collation_by_id(restore_collation_id_if_needed(c) as isize) {
        return coll.name.clone();
    }
    log::warn!(
        "Unable to get collation name from ID, use name of the default collation instead id={c} default collation ID={} default collation={}",
        mysql::DefaultCollationID,
        mysql::DefaultCollationName
    );
    mysql::DefaultCollationName.to_owned()
}

/// The registry `newCollatorMap` / `newCollatorIDMap` (Go also sets `newCollationEnabled`
/// to 1 here, which is the initial value of the atomic).
// go: init L1
fn init() -> CollatorMaps {
    let mut new_collator_map: HashMap<&'static str, Box<dyn Collator>> = HashMap::new();
    let mut new_collator_id_map: HashMap<isize, Box<dyn Collator>> = HashMap::new();

    let mut add = |name: &'static str, ctor: fn() -> Box<dyn Collator>| {
        new_collator_map.insert(name, ctor());
        new_collator_id_map.insert(collation_name2_id(name), ctor());
    };
    add("binary", || Box::new(BinCollator));
    add("ascii_bin", || Box::new(BinPaddingCollator));
    add("latin1_bin", || Box::new(BinPaddingCollator));
    add("utf8mb4_bin", || Box::new(BinPaddingCollator));
    add("utf8_bin", || Box::new(BinPaddingCollator));
    add("utf8mb4_0900_bin", || Box::new(DerivedBinCollator::new()));
    add("utf8mb4_general_ci", || Box::new(GeneralCICollator));
    add("utf8_general_ci", || Box::new(GeneralCICollator));
    add("utf8mb4_unicode_ci", || {
        Box::new(UnicodeCICollator::default())
    });
    add("utf8mb4_0900_ai_ci", || {
        Box::new(Unicode0900AICICollator::default())
    });
    add("utf8_unicode_ci", || Box::new(UnicodeCICollator::default()));
    add("utf8mb4_zh_pinyin_tidb_as_cs", || {
        Box::new(ZhPinyinTiDBASCSCollator)
    });
    add(gocharset::CollationGBKBin, || {
        Box::new(GbkBinCollator::new())
    });
    add(gocharset::CollationGBKChineseCI, || {
        Box::new(GbkChineseCICollator)
    });
    (new_collator_map, new_collator_id_map)
}
